vector<int> inorder(TreeNode* root) {
    vector<int> out;
    stack<TreeNode*> st;
    TreeNode* cur = root;
    while (cur || !st.empty()) {
        while (cur) { st.push(cur); cur = cur->left; }  // dive left
        cur = st.top(); st.pop();                       // visit
        out.push_back(cur->val);
        cur = cur->right;                               // switch lane
    }
    return out;
}

queue<TreeNode*> q; q.push(root);
while (!q.empty()) {
    int sz = q.size();                    // freeze layer size!
    vector<int> level;
    for (int i = 0; i < sz; i++) {
        auto n = q.front(); q.pop();
        level.push_back(n->val);
        if (n->left) q.push(n->left);
        if (n->right) q.push(n->right);
    }
    ans.push_back(level);                 // reverse on odd rows for zigzag
}

