// DIAMETER: height and best-through-path travel together
int dia = 0;
int ht(TreeNode* r){
    if(!r) return 0;
    int L = ht(r->left), R = ht(r->right);
    dia = max(dia, L + R);            // path THROUGH this node
    return max(L, R) + 1;             // height component
}
// BALANCED: height OR -1 sentinel
int chk(TreeNode* r){
    if(!r) return 0;
    int L = chk(r->left); if (L < 0) return -1;
    int R = chk(r->right); if (R < 0) return -1;
    return abs(L - R) > 1 ? -1 : max(L, R) + 1;
}
